namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private readonly List<Notification> _notifications = new();
    private int _nextId;

    public NotificationService()
    {
        // Seed with initial fake data.
        _notifications.AddRange(new[]
        {
            new Notification(++_nextId, "Welcome to the app!", DateTime.UtcNow.AddMinutes(-30)),
            new Notification(++_nextId, "Your profile was updated.", DateTime.UtcNow.AddMinutes(-15)),
            new Notification(++_nextId, "New feature: dark mode is available.", DateTime.UtcNow.AddMinutes(-5)),
        });
    }

    /// <summary>Returns all notifications.</summary>
    public Task<IReadOnlyList<Notification>> GetAllAsync()
    {
        lock (_notifications)
        {
            return Task.FromResult<IReadOnlyList<Notification>>(_notifications.ToList());
        }
    }

    /// <summary>Returns notifications added after the given timestamp.</summary>
    public Task<IReadOnlyList<Notification>> GetNewerThanAsync(DateTime since)
    {
        lock (_notifications)
        {
            var results = _notifications.Where(n => n.Timestamp > since).ToList();
            return Task.FromResult<IReadOnlyList<Notification>>(results);
        }
    }

    /// <summary>Simulates an incoming notification (called by background generator).</summary>
    public void Add(string message)
    {
        lock (_notifications)
        {
            _notifications.Add(new Notification(++_nextId, message, DateTime.UtcNow));
        }
    }
}

namespace NotificationsApp.Services;

/// <summary>
/// Background service that adds a fake notification every ~8 seconds
/// so there is something for the polling loop to pick up.
/// </summary>
public class FakeNotificationGenerator : BackgroundService
{
    private static readonly string[] Messages =
    [
        "Server deployment completed successfully.",
        "A new user signed up.",
        "Disk usage exceeded 80%.",
        "Scheduled backup finished.",
        "Security scan completed — no issues found.",
        "New comment on your pull request.",
        "CI pipeline passed for main branch.",
    ];

    private readonly NotificationService _svc;

    public FakeNotificationGenerator(NotificationService svc) => _svc = svc;

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        var rng = new Random();
        while (!stoppingToken.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(8), stoppingToken);
            _svc.Add(Messages[rng.Next(Messages.Length)]);
        }
    }
}

